arguments.command:
cd /tmp/ross-conv && cat /tmp/unrecorded.txt | head -5; echo "---sample episode distribution---"; 
# get episode from each unrecorded sha
awk '{print $1}' /tmp/unrecorded.txt | while read sha; do git show -s --format='%B' $sha | grep -i '^Episode:' ; done | sort | uniq -c | tail -30
